INSERT OR IGNORE INTO posts (slug, cover, title_de, title_en, title_ar, excerpt_de, excerpt_en, excerpt_ar, body_de, body_en, body_ar) VALUES ('schwarze-seife-anwendung', '/assets/p/schwarze-seife-eukalyptus-pack.webp', 'Schwarze Seife richtig anwenden: die Anleitung für das Hammam zu Hause', 'How to use Moroccan black soap: the hammam at home', 'طريقة استعمال الصابون البلدي: الحمام في بيتك', 'Was ist marokkanische schwarze Seife (Savon Beldi) und wie wendet man sie richtig an? Schritt für Schritt zum Hammam-Gefühl im eigenen Bad.', 'What is Moroccan black soap (savon beldi) and how do you use it? Step by step to the hammam feeling at home.', 'ما هو الصابون البلدي المغربي وكيف يُستعمل؟ خطوة بخطوة نحو إحساس الحمام في بيتك.', '<p>Die schwarze Seife, auf Marokkanisch <strong>Savon Beldi</strong>, ist der Mittelpunkt jedes Hammam-Besuchs in Marokko. Anders als eine feste Seife ist sie weich und pastenartig. Sie wird nicht aufgeschäumt, sondern auf die Haut aufgetragen und wirkt kurz ein.</p><h2>Was macht schwarze Seife besonders?</h2><p>Schwarze Seife bereitet die Haut auf das Peeling vor. Nach der Einwirkzeit lassen sich abgestorbene Hautschüppchen mit einem Kessa-Handschuh besonders leicht lösen. Das Ergebnis ist ein samtweiches Hautgefühl, das man aus dem marokkanischen Hammam kennt.</p><h2>Anwendung in 5 Schritten</h2><ol><li><strong>Wärme:</strong> Duschen oder baden Sie einige Minuten warm.</li><li><strong>Auftragen:</strong> Eine kleine Menge schwarze Seife auf der feuchten Haut verteilen.</li><li><strong>Einwirken:</strong> 5–10 Minuten wirken lassen, am besten im warmen Bad.</li><li><strong>Abspülen und peelen:</strong> Abspülen und die Haut mit dem Kessa-Handschuh in langen Bewegungen abreiben.</li><li><strong>Pflegen:</strong> Zum Abschluss ein paar Tropfen Öl einmassieren.</li></ol><h2>Wie oft?</h2><p>Ein- bis zweimal pro Woche genügt. Bei empfindlicher Haut beginnen Sie mit einer kürzeren Einwirkzeit und machen vorher einen Verträglichkeitstest.</p><h2>Welche schwarze Seife passt zu mir?</h2><p>Bei Khachija gibt es schwarze Seife mit <strong>Eukalyptus</strong> (frisch und klärend), mit <strong>Aker Fasi</strong> (dem traditionellen Rot aus Fès) und mit <strong>Nila</strong> aus dem Süden Marokkos.</p>', '<p>Moroccan black soap, <strong>savon beldi</strong>, is at the heart of every hammam visit in Morocco. Unlike a bar of soap, it is soft and paste-like: you apply it to the skin and leave it on briefly.</p><h2>How to use it in 5 steps</h2><ol><li>Take a warm shower or bath for a few minutes.</li><li>Spread a little black soap on damp skin.</li><li>Leave it on for 5–10 minutes.</li><li>Rinse and exfoliate with a kessa glove in long strokes.</li><li>Finish with a few drops of oil.</li></ol><p>Once or twice a week is enough. With sensitive skin, start with a shorter time and do a patch test first.</p>', '<p>الصابون البلدي هو قلب كل زيارة للحمام في المغرب. يُوضع على البشرة المبللة ويُترك قليلًا قبل الشطف.</p><h2>الاستعمال في 5 خطوات</h2><ol><li>استحمي بماء دافئ لبضع دقائق.</li><li>ضعي قليلًا من الصابون البلدي على البشرة المبللة.</li><li>اتركيه من 5 إلى 10 دقائق.</li><li>اشطفي ثم قشري بالكيس.</li><li>اختمي ببضع قطرات من الزيت.</li></ol>');
INSERT OR IGNORE INTO posts (slug, cover, title_de, title_en, title_ar, excerpt_de, excerpt_en, excerpt_ar, body_de, body_en, body_ar) VALUES ('nila-pulver-blaues-geheimnis', '/assets/p/nila-seife-2.webp', 'Nila: das blaue Schönheitsgeheimnis der Sahara', 'Nila: the blue beauty secret of the Sahara', 'النيلة: سر الجمال الأزرق للصحراء', 'Woher kommt das blaue Nila, wie wird es traditionell verwendet und welche Nila-Produkte passen zu Ihrer Pflege?', 'Where does blue nila come from, how is it traditionally used and which nila products suit your routine?', 'من أين تأتي النيلة الزرقاء وكيف تُستعمل تقليديًا؟', '<p><strong>Nila</strong> ist ein leuchtend blaues Schönheitsmittel aus dem Süden Marokkos. Seit Generationen gehört es zu den Pflegeritualen der Frauen in der Sahara, besonders im Hammam und vor besonderen Anlässen.</p><h2>Wie wird Nila verwendet?</h2><p>Traditionell wird Nila in Seifen, Peelings und Masken verwendet. Es schenkt ein klares, frisches Hautgefühl und gehört zum klassischen Hammam-Ritual.</p><h2>Nila-Produkte bei Khachija</h2><ul><li><strong>Nilla Seife (120 g):</strong> für die tägliche Pflege von Gesicht und Körper.</li><li><strong>Gommage (Peeling) Nilla (200 g):</strong> klärend und aufhellend, für alle Hauttypen.</li><li><strong>Maske Nilla (100 g):</strong> für das wöchentliche Ritual.</li></ul><h2>Tipp</h2><p>Nila kann leicht abfärben. Spülen Sie Waschbecken und Dusche nach der Anwendung kurz aus und verwenden Sie ein dunkles Handtuch.</p>', '<p><strong>Nila</strong> is a bright blue beauty ingredient from southern Morocco, part of the care rituals of Saharan women for generations. Traditionally it is used in soaps, scrubs and masks for a clear, fresh skin feeling.</p><h2>Nila at Khachija</h2><ul><li>Nilla soap (120 g) for face and body.</li><li>Nilla gommage (200 g), clarifying, for all skin types.</li><li>Nilla mask (100 g) for the weekly ritual.</li></ul><p>Tip: nila can colour slightly, so rinse the basin after use and use a dark towel.</p>', '<p><strong>النيلة</strong> مكون تجميلي أزرق من جنوب المغرب، جزء من طقوس العناية لدى نساء الصحراء منذ أجيال. تُستعمل تقليديًا في الصابون والتقشير والأقنعة.</p>');
INSERT OR IGNORE INTO posts (slug, cover, title_de, title_en, title_ar, excerpt_de, excerpt_en, excerpt_ar, body_de, body_en, body_ar) VALUES ('sidr-pulver-haare', '/assets/p/sidr-1.webp', 'Sidr Pulver für die Haare: Anwendung und Tipps', 'Sidr powder for hair: how to use it', 'مسحوق السدر للشعر: طريقة الاستعمال', 'Sidr ist eine sanfte Pflanzenwäsche aus den Blättern des Sidr-Baums. So wenden Sie Sidr-Pulver für Haar und Kopfhaut an.', 'Sidr is a gentle plant wash from the leaves of the sidr tree. How to use sidr powder for hair and scalp.', 'السدر غسول نباتي لطيف من أوراق شجرة السدر. هكذا تستعملينه للشعر.', '<p>Das <strong>Sidr-Pulver</strong> wird aus den getrockneten Blättern des Sidr-Baums (Christusdorn) gemahlen. Im Orient und in Nordafrika wird es seit Jahrhunderten als milde, natürliche Haar- und Hautwäsche verwendet.</p><h2>So wenden Sie Sidr an</h2><ol><li>2–3 Esslöffel Sidr-Pulver mit warmem Wasser zu einer cremigen Paste verrühren.</li><li>Auf das feuchte Haar und die Kopfhaut auftragen und sanft einmassieren.</li><li>10–20 Minuten einwirken lassen.</li><li>Gründlich mit warmem Wasser ausspülen.</li></ol><h2>Sidr und Henna kombinieren</h2><p>Viele Frauen kombinieren Sidr mit <strong>Henna</strong>: Sidr für die sanfte Reinigung, Henna für Pflege und natürlichen Glanz. Zum Abschluss ein paar Tropfen <strong>Rizinusöl</strong> in die Spitzen geben.</p><p>Machen Sie vor der ersten Anwendung immer einen Verträglichkeitstest.</p>', '<p><strong>Sidr powder</strong> is ground from the dried leaves of the sidr tree and has been used for centuries as a mild, natural wash for hair and skin.</p><h2>How to use</h2><ol><li>Mix 2–3 tablespoons with warm water into a creamy paste.</li><li>Apply to damp hair and scalp and massage gently.</li><li>Leave on for 10–20 minutes.</li><li>Rinse thoroughly with warm water.</li></ol><p>Many women combine sidr with henna, and finish with a few drops of castor oil on the ends. Always do a patch test first.</p>', '<p>يُطحن <strong>مسحوق السدر</strong> من أوراق شجرة السدر المجففة، ويُستعمل منذ قرون غسولًا طبيعيًا لطيفًا للشعر والبشرة.</p><ol><li>اخلطي 2 إلى 3 ملاعق بماء دافئ.</li><li>ضعيه على الشعر وفروة الرأس ودلكي بلطف.</li><li>اتركيه من 10 إلى 20 دقيقة ثم اشطفي.</li></ol>');
INSERT OR IGNORE INTO posts (slug, cover, title_de, title_en, title_ar, excerpt_de, excerpt_en, excerpt_ar, body_de, body_en, body_ar) VALUES ('rizinusoel-wimpern-haare', '/assets/p/rizinusoel-1.webp', 'Rizinusöl für Wimpern, Augenbrauen und Haare: so geht’s', 'Castor oil for lashes, brows and hair: how to use it', 'زيت الخروع للرموش والحواجب والشعر', 'Rizinusöl ist ein traditionelles Pflegeöl. So wenden Sie es richtig für Wimpern, Augenbrauen und Haare an.', 'Castor oil is a traditional care oil. How to use it for lashes, brows and hair.', 'زيت الخروع زيت عناية تقليدي. هكذا تستعملينه للرموش والحواجب والشعر.', '<p><strong>Rizinusöl</strong> wird aus den Samen der Rizinuspflanze gewonnen. Es ist dickflüssig und reichhaltig und gehört seit Generationen zu den beliebtesten natürlichen Pflegeölen.</p><h2>Für Wimpern und Augenbrauen</h2><p>Tragen Sie abends mit einem sauberen Wimpernbürstchen eine sehr kleine Menge auf Wimpern und Augenbrauen auf. Das Öl darf nicht in die Augen gelangen. Morgens einfach abwaschen.</p><h2>Für die Haare</h2><ol><li>Einige Tropfen in den Handflächen erwärmen.</li><li>In Kopfhaut und Spitzen einmassieren.</li><li>Mindestens 30 Minuten oder über Nacht einwirken lassen.</li><li>Gründlich auswaschen, eventuell zweimal shampoonieren.</li></ol><h2>Für trockene Haut</h2><p>Ein paar Tropfen an Ellbogen, Knien oder Fersen einmassieren. Wegen der dicken Konsistenz reicht eine kleine Menge.</p>', '<p><strong>Castor oil</strong> comes from the seeds of the castor plant. Thick and rich, it is one of the most popular natural care oils.</p><h2>Lashes and brows</h2><p>In the evening, apply a tiny amount with a clean lash brush. Keep it out of your eyes, and wash it off in the morning.</p><h2>Hair</h2><p>Warm a few drops between your palms, massage into scalp and ends, leave on for at least 30 minutes or overnight, then wash out thoroughly.</p>', '<p><strong>زيت الخروع</strong> زيت كثيف وغني يُستخرج من بذور نبتة الخروع.</p><h2>للرموش والحواجب</h2><p>ضعي كمية صغيرة جدًا مساءً بفرشاة نظيفة، وتجنبي العينين.</p><h2>للشعر</h2><p>دلكي بضع قطرات في فروة الرأس والأطراف، واتركيه 30 دقيقة على الأقل ثم اغسليه جيدًا.</p>');
